content.text:
The root cause is a single HTTP-level slowdown on ts-travel2-service's outgoing `GET /routes/{routeId}` calls. Only the admin travel path is affected for users, and the chain runs travel2 → admin-travel → ui-dashboard.

```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration/1e6,0.5),1) p50_client_ms, round(quantile_cont(c.duration/1e6,0.5),1) p50_server_ms, round(quantile_cont((epoch_ms(c.time)-epoch_ms(p.time)),0.5),1) med_start_offset_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND c.attr_span_kind='Server' AND p.service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "travel2's GET calls to route-service take ~209ms at client but only ~1.7ms in the server span; the gap is before the server span starts."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(quantile_cont(p.duration/1e6,0.5),1) p50_client_ms, round(quantile_cont(c.duration/1e6,0.5),1) p50_server_ms FROM normal_traces p JOIN normal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.service_name='ts-route-service' AND c.attr_span_kind='Server' AND p.service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "In the normal period the same travel2-to-route GET calls took about 1.7ms at client and server."
        },
        {
          "kind": "trace",
          "sql": "SELECT c.service_name callee_svc, c.span_name, count(*) n, round(quantile_cont(p.duration/1e6,0.5),1) p50_client_ms, round(quantile_cont(c.duration/1e6,0.95),1) p95_child_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id AND c.attr_span_kind='Server' WHERE p.service_name='ts-travel2-service' AND p.attr_span_kind='Client' GROUP BY 1,2 ORDER BY n DESC",
          "claim": "Only travel2's GET to route-service is slow; its POST to basic-service and GET to train-service stay at normal latency."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-admin-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name callee, count(*) n, round(quantile_cont(p.duration/1e6,0.5),1) p50_client_ms, round(quantile_cont(c.duration/1e6,0.95),1) p95_child_ms FROM abnormal_traces p JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id AND c.attr_span_kind='Server' WHERE p.service_name='ts-admin-travel-service' AND p.attr_span_kind='Client' AND c.service_name='ts-travel2-service' GROUP BY 1",
          "claim": "admin-travel's GET calls to travel2 now take a median of ~859ms and p95 ~3.76s, versus ~27ms at p95 normally."
        }
      ]
    },
    {
      "from": "ts-admin-travel-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' per, span_name, count(*) n, round(quantile_cont(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='GET /api/v1/admintravelservice/admintravel' GROUP BY 1,2 UNION ALL SELECT 'norm', span_name, count(*), round(quantile_cont(duration/1e6,0.95),1) FROM normal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name='GET /api/v1/admintravelservice/admintravel' GROUP BY 1,2",
          "claim": "ui-dashboard's admin travel endpoint p95 rose from ~66ms to ~4.3s; other dashboard endpoints stayed within normal range."
        }
      ]
    }
  ]
}
```

